    /// # Safety
    /// `ptr` must be a valid `vtkTextureUnitManager *` and the caller transfers one reference.
    #[inline]
    pub(crate) unsafe fn from_owned(ptr: *mut c_void) -> Option<Self> {
        NonNull::new(ptr).map(Self)
    }

    /// Wrap a borrowed pointer, taking an extra reference.
